DO $$ DECLARE
  x integer := 1;
  y text := 'a';
BEGIN
  PERFORM x;
END $$;

DO $$ BEGIN
BEGIN
  PERFORM 1;
EXCEPTION WHEN OTHERS THEN NULL;
END;
END $$;

DO $$ DECLARE
  x integer := 1;
BEGIN
  DECLARE
    y integer := x + 1;
  BEGIN
    PERFORM y;
  END;
END $$;

DO $$ BEGIN
  IF true THEN
    CALL s.p(1);
  END IF;
END $$;

CREATE PROCEDURE s.pout(INOUT result integer) LANGUAGE plpgsql AS $$ BEGIN result := result * 2; END $$;
CALL s.pout(5);
DROP PROCEDURE s.pout(integer);

CREATE PROCEDURE s.pout2(IN a integer, INOUT b integer) LANGUAGE plpgsql AS $$ BEGIN b := a + b; END $$;
CALL s.pout2(3, 4);
DROP PROCEDURE s.pout2(integer, integer);

CREATE PROCEDURE s.pout3(OUT x integer) LANGUAGE plpgsql AS $$ BEGIN x := 42; END $$;
CALL s.pout3(NULL);
DROP PROCEDURE s.pout3(integer);

CREATE PROCEDURE s.pmulti(IN a integer, IN b integer, OUT c integer) LANGUAGE plpgsql AS $$ BEGIN c := a + b; END $$;
CALL s.pmulti(1, 2, NULL);
DROP PROCEDURE s.pmulti(integer, integer, integer);

CREATE PROCEDURE s.pnamed(IN x integer DEFAULT 10, IN y integer DEFAULT 20) LANGUAGE plpgsql AS $$ BEGIN PERFORM x + y; END $$;
CALL s.pnamed();
DROP PROCEDURE s.pnamed(integer, integer);

CREATE PROCEDURE s.pnamed2(IN x integer DEFAULT 10, IN y integer DEFAULT 20) LANGUAGE plpgsql AS $$ BEGIN PERFORM x + y; END $$;
CALL s.pnamed2(y => 5);
DROP PROCEDURE s.pnamed2(integer, integer);
